{"filePath":"/testbed/config_loader.py","content":""""Loader for versioned local maintainer profiles; see README.md."""

import importlib


def _evaluate(expression: str):
    return eval(expression, {}, {})


def load_config(text: str) -> dict:
    settings = {}
    plugin = None
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue
        key, separator, value = line.partition('=')
        if not separator:
            raise ValueError(f'invalid line in profile (expected key = value): {raw_line!r}')
        key = key.strip()
        evaluated = _evaluate(value.strip())
        if key == 'plugin':
            module = importlib.import_module(evaluated)
            plugin = module.Transform()
        else:
            settings[key] = evaluated
    return {'settings': settings, 'plugin': plugin}
"}
